/**
 * Runtime supervisor: starts the runtimes the web application hosts and stops them with it.
 *
 * A runtime that fails to start is restarted with bounded exponential backoff and jitter; it
 * never takes the web app down. A consumer runtime counts as down -- and the health controller's
 * readiness gate reports it -- from bootstrap until it has started, and again while a failed
 * start is waiting to be retried.
 *
 * Auto-generated by cruftfree-codegen-typescript. Do not edit manually.
 */
import type { Logger } from '@nestjs/common';

export type Stop = () => Promise<void>;

export interface Runtime {
  readonly name: string;
  readonly start: () => Promise<Stop>;
  /** Whether this runtime consumes events: while it is not started, the service is not ready. */
  readonly consumes: boolean;
}

// Bounded exponential backoff between restarts of a runtime that failed to start.
const RETRY_BASE_MS = 1000;
const RETRY_MAX_MS = 30000;
const STOP_POLL_SLICE_MS = 250;

export class RuntimeSupervisor {
  private readonly stops: Stop[] = [];
  /** The consumer runtimes not started yet, or waiting to retry a failed start. */
  private readonly downConsumers = new Set<string>();
  private stopping = false;
  private started: Promise<void> = Promise.resolve();

  constructor(private readonly logger: Logger) {}

  /** Begin starting *runtimes*; it does not wait for them: readiness reports the wait. */
  start(runtimes: readonly Runtime[]): void {
    // Fail closed: a consumer is down until it reports started.
    for (const runtime of runtimes) {
      if (runtime.consumes) {
        this.downConsumers.add(runtime.name);
      }
    }
    this.started = Promise.all(runtimes.map((runtime) => this.superviseStart(runtime))).then(
      () => undefined,
    );
  }

  /** Whether any consumer runtime is not running: the readiness gate's consumer blocker. */
  consumersDown(): boolean {
    return this.downConsumers.size > 0;
  }

  /** Stop every started runtime, last started first; a failed stop never blocks the others. */
  async stop(): Promise<void> {
    this.stopping = true;
    await this.started;
    for (const stop of this.stops.splice(0).reverse()) {
      try {
        await stop();
      } catch (err) {
        this.logger.error(`runtime_stop_failed error=${describe(err)}`);
      }
    }
  }

  /** Start *runtime*, retrying with bounded backoff until it starts or the app stops. */
  private async superviseStart(runtime: Runtime): Promise<void> {
    let delayMs = RETRY_BASE_MS;
    while (!this.stopping) {
      try {
        const stop = await runtime.start();
        if (this.stopping) {
          await stop();
          return;
        }
        this.stops.push(stop);
        this.downConsumers.delete(runtime.name);
        this.logger.log(`runtime_started runtime=${runtime.name}`);
        return;
      } catch (err) {
        if (runtime.consumes) {
          this.downConsumers.add(runtime.name);
        }
        const waitMs = Math.round(delayMs * (0.5 + Math.random() / 2));
        this.logger.error(
          `runtime_start_failed runtime=${runtime.name} retry_in_ms=${waitMs} error=${describe(err)}`,
        );
        await this.waitUnlessStopping(waitMs);
        delayMs = Math.min(delayMs * 2, RETRY_MAX_MS);
      }
    }
  }

  /** Wait *delayMs*, sliced so that stopping the application ends the wait promptly. */
  private async waitUnlessStopping(delayMs: number): Promise<void> {
    let waitedMs = 0;
    while (!this.stopping && waitedMs < delayMs) {
      const sliceMs = Math.min(STOP_POLL_SLICE_MS, delayMs - waitedMs);
      await new Promise((resolve) => setTimeout(resolve, sliceMs));
      waitedMs += sliceMs;
    }
  }
}

function describe(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}
